def simulate(g, vpolicy='last'):
    g = np.array(g); R,C = g.shape
    dia = find_diamonds(g)
    whites = [d for d in dia if d[2]==0]
    e = whites[0] if whites else None
    col_d = [d for d in dia if d[2]!=0]
    newpos = []
    for (r,c,v) in col_d:
        if e is None:
            newpos.append((r,c,v)); continue
        dr,dc = e[0]-r, e[1]-c
        conflict = (e[0]==r) or (e[1]==c)
        if conflict:
            if abs(dr)>=abs(dc): move=(r+(1 if dr>0 else -1), c)
            else: move=(r, c+(1 if dc>0 else -1))
        else:
            move = (r, c+(1 if dc>0 else -1)) if abs(dc)>abs(dr) else (r,c)
        newpos.append((move[0],move[1],v))
    out = g.copy()
    cells = lambda r,c: [(r-1,c),(r+1,c),(r,c-1),(r,c+1),(r,c)]
    for (r,c,v) in col_d + whites:
        for (rr,cc) in cells(r,c): out[rr,cc]=0
    for (r,c,v) in newpos + whites:
        for (rr,cc) in cells(r,c)[:4]: out[rr,cc]=3
        out[r,c]=v
    er,ec = (e[0],e[1]) if e else (None,None)
    # Phase H: paint only 0-cells, stop at other 3s, pass own ring
    def rowbeam(r, c, v):
        for cc in range(c-1,-1,-1):
            if out[r,cc]==3:
                if (r,cc) in ownrings: continue
                break
            if out[r,cc]==0: out[r,cc]=v
        for cc in range(c+1,C):
            if out[r,cc]==3:
                if (r,cc) in ownrings: continue
                break
            if out[r,cc]==0: out[r,cc]=v
    ownrings = set((r,c) for (r,c,v) in newpos+whites for (r,c) in cells(r,c)[:4])
    # careful: need per-diamond rings; do per-diamond
    allpos = newpos + (whites if whites else [])
    for (r,c,v) in allpos:
        own = set(cells(r,c)[:4])
        for cc in range(c-1,-1,-1):
            if out[r,cc]==3:
                if (r,cc) in own: continue
                break
            if out[r,cc]==0: out[r,cc]=v
        for cc in range(c+1,C):
            if out[r,cc]==3:
                if (r,cc) in own: continue
                break
            if out[r,cc]==0: out[r,cc]=v
    # Phase V: colored verticals
    vcols = {}
    for idx,(r,c,v) in enumerate(newpos):
        vcols.setdefault(c,[]).append((idx,r,v))
    for c,lst in vcols.items():
        lst = sorted(lst, key=lambda t:t[1])
        painted = {}
        for (idx,r,v) in lst:
            own = set((cells(r,c)[:4]))
            for rr in range(r-1,-1,-1):
                if out[rr,c]==3:
                    if (rr,c) in own: continue
                    break
                painted[rr]=v
            for rr in range(r+1,R):
                if out[rr,c]==3:
                    if (rr,c) in own: continue
                    break
                painted[rr]=v
        items = sorted(painted.items())
        if vpolicy=='last':
            pass  # dict already last-wins per diamond order
        out[rr:=c and rr or 0,0] = out[0,0]  # noop
        for rr,vv in painted.items():
            out[rr,c]=vv
    if e is not None:
        for rr in range(R):
            if out[rr,ec]!=3: out[rr,ec]=0
    return out

